import{_ as a,o as i,c as r,a4 as l}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"AI 开发 Harness 设计","description":"","frontmatter":{"title":"AI 开发 Harness 设计","date":"2026-06-27T00:00:00.000Z"},"headers":[],"relativePath":"posts/AI开发框架共识与Harness设计.md","filePath":"posts/AI开发框架共识与Harness设计.md"}'),t={name:"posts/AI开发框架共识与Harness设计.md"};function s(n,e,o,c,h,p){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="ai-开发-harness-设计" tabindex="-1">AI 开发 Harness 设计 <a class="header-anchor" href="#ai-开发-harness-设计" aria-label="Permalink to &quot;AI 开发 Harness 设计&quot;">​</a></h1><h2 id="一、核心痛点共识" tabindex="-1">一、核心痛点共识 <a class="header-anchor" href="#一、核心痛点共识" aria-label="Permalink to &quot;一、核心痛点共识&quot;">​</a></h2><ul><li>AI 编程现状：生成容易，修改极难。AI 视代码为线性文本，人类视代码为二维空间。</li><li>软件真正敌人：耦合度与隐式上下文（如 Spring 的式注入、运行时魔法）。</li></ul><h2 id="二、终极方法论-反魔法-画图取代写代码" tabindex="-1">二、终极方法论：反魔法，画图取代写代码 <a class="header-anchor" href="#二、终极方法论-反魔法-画图取代写代码" aria-label="Permalink to &quot;二、终极方法论：反魔法，画图取代写代码&quot;">​</a></h2><ul><li>语言本质有损压缩脑中的三维逻辑。</li><li>程序本质：约束快照。</li><li>系统本质：状态与事件的博弈核心操作：放弃堆砌 Service，改为维护状态图。YAML/表格即源码，代码仅为渲染产物。</li></ul><h2 id="三、三层物理架构-告别-controller-service-mapper" tabindex="-1">三、三层物理架构（告别 Controller/Service/Mapper） <a class="header-anchor" href="#三、三层物理架构-告别-controller-service-mapper" aria-label="Permalink to &quot;三、三层物理架构（告别 Controller/Service/Mapper）&quot;">​</a></h2><ol><li><strong>函数层（Domain）</strong>：纯业务规则，零外部依赖，仅做计算，输入输出显式传递。</li><li><strong>适配层（Infra）</strong>：对接外部世界（DB/HTTP/MQTT）。</li><li><strong>胶水层（App/Main）</strong>：显式编排，手动组装依赖，消灭 @Autowired 和 init()。</li></ol><h2 id="四、性能与高并发硬核解法" tabindex="-1">四、性能与高并发硬核解法 <a class="header-anchor" href="#四、性能与高并发硬核解法" aria-label="Permalink to &quot;四、性能与高并发硬核解法&quot;">​</a></h2><ul><li>纯函数改为传入指针 + sync.Pool 复用对象，消灭 GC 压力。</li><li>状态机编译为整数常量二维数组，走 CPU 指令级查表，拒绝运行时反射/Map。</li></ul><h2 id="五、框架致命边界" tabindex="-1">五、框架致命边界 <a class="header-anchor" href="#五、框架致命边界" aria-label="Permalink to &quot;五、框架致命边界&quot;">​</a></h2><ul><li><strong>适合</strong>：业务可穷举、延迟容忍&gt;1ms、团队≤5人、无强制全局初始化。</li><li><strong>不适合</strong>：高频交易、混沌 AI Agent、强依赖遗留 C 库（此时可合法放弃纯净教条） 六、不恶心框架的最终形态无魔法注解、无全局变量、无自动扫描。</li><li>目录结构：specs/（画板）+ domain/（纯函数）+ infra/（实现）+ main.go（显式组装）。</li><li>改业务：改 specs 下状态 YAML，AI 重生成代码改技术：仅改 infra，domain 毫不知情 七、Harness 设计（框架约束 + Harness 发力） Harness 是套在 AI 脖子上的缰绳+验证器，解决“AI 写的东西怎么保证没错”。</li></ul><h3 id="_1-specs-校验器-pre-generation" tabindex="-1">1. Specs 校验器（Pre-generation） <a class="header-anchor" href="#_1-specs-校验器-pre-generation" aria-label="Permalink to &quot;1. Specs 校验器（Pre-generation）&quot;">​</a></h3><ul><li>检查 YAML 状态图完备性（无死锁、无不可达状态、类型匹配）工具：CUE / TypeSpec / 自定义 AST walker作用：AI 动手前拦掉需求错误。\\2. 生成后静态门禁（Post-generation）</li><li>强制 lint + typecheck + import 白名单（domain 禁 import infra/http/sql）。</li><li>工具：golangci-lint / rustc / 自定义规则引擎。</li><li>作用：确保生成代码不破坏三层架构边界。\\3. 节点级契约测试（Per-node）</li><li>基于 specs 前置/后置条件自动生成 property-based test。\\：Go testing/quickcheck / Rust proptest。 单节点修改即时验证行为合规性。</li></ul><h3 id="_4-diff-审计钩子-human-in-the-loop" tabindex="-1">4. Diff 审计钩子（Human-in-the-loop） <a class="header-anchor" href="#_4-diff-审计钩子-human-in-the-loop" aria-label="Permalink to &quot;4. Diff 审计钩子（Human-in-the-loop）&quot;">​</a></h3><ul><li>自动高亮生成差异，标注是否超出 specs 允许范围。</li><li>工具：git diff + 自定义注解器。 人只看变化点，review 效率拉满 八、人机协作终极形态 上层：人类用 specs 写意图（零代码、纯逻辑、可版本化）下层：AI 翻译为实现（零决策、纯执行、可丢弃、可重 中间靠类型系统 + 状态图校验 + 编译门禁卡死。</li><li>代码不再是资产，specs 才是。</li></ul>',15)])])}const _=a(t,[["render",s]]);export{u as __pageData,_ as default};
